func testAnimalEspecieToManyRemoveOpAnieEntidadeAnimals(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a AnimalEspecie
	var b, c, d, e EntidadeAnimal

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, animalEspecieDBTypes, false, strmangle.SetComplement(animalEspeciePrimaryKeyColumns, animalEspecieColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*EntidadeAnimal{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, entidadeAnimalDBTypes, false, strmangle.SetComplement(entidadeAnimalPrimaryKeyColumns, entidadeAnimalColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddAnieEntidadeAnimals(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.AnieEntidadeAnimals().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveAnieEntidadeAnimals(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.AnieEntidadeAnimals().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.AnieID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.AnieID) {
		t.Error("want c's foreign key value to be nil")
	}

	if b.R.Anie != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Anie != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Anie != &a {
		t.Error("relationship to a should have been preserved")
	}
	if e.R.Anie != &a {
		t.Error("relationship to a should have been preserved")
	}

	if len(a.R.AnieEntidadeAnimals) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.AnieEntidadeAnimals[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.AnieEntidadeAnimals[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

